package resolveit.access;

/** Defines the failed-attempt threshold used to determine account lockout. */
public final class AccessPolicy {
    private final int maxAttempts;

    /**
     * Creates an access policy with the specified maximum number of failed attempts.
     *
     * @param maxAttempts the number of failed attempts at which access is locked out
     */
    public AccessPolicy(int maxAttempts) {
        this.maxAttempts = maxAttempts;
    }

    /**
     * Determines whether the specified number of failed attempts has reached the lockout threshold.
     *
     * @param failedAttempts the number of failed access attempts
     * @return {@code true} if access should be locked out; {@code false} otherwise
     */
    public boolean isLockedOut(int failedAttempts) {
        return failedAttempts >= maxAttempts;
    }

    /**
     * Calculates how many failed attempts remain before lockout.
     *
     * @param failedAttempts the number of failed access attempts
     * @return the number of attempts remaining, or {@code 0} if the threshold has been reached
     */
    public int remainingAttempts(int failedAttempts) {
        int remaining = maxAttempts - failedAttempts;
        return Math.max(remaining, 0);
    }
}

package resolveit.access;

public final class SessionClock {
    private long lastActivityMillis;

    public SessionClock(long startMillis) {
        this.lastActivityMillis = startMillis;
    }

    public void touch(long nowMillis) {
        this.lastActivityMillis = nowMillis;
    }

    public boolean isExpired(long nowMillis, long timeoutMillis) {
        return nowMillis - lastActivityMillis > timeoutMillis;
    }
}

